using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Arith.QuadraticFields;

internal sealed class QuadraticAccumulationClassificationDocument : IScribeDocumentDefinition
{
    private static readonly LibraryNoteRef Source =
        LibraryNoteRef.Create("D5/L/QuadraticForms/dhandahaynes2025accumulation");

    private static DocumentBlock Item(string selector, string description, DescribeRole role) =>
        Describe.Lean(DescribeId.Create("quadraticaccumulationclassification-" + selector.Replace("_", "-").ToLowerInvariant()),
            DeclarationHandle.Create("D5/S3/Arith/QuadraticFields/QuadraticAccumulationClassification." + selector),
            H(selector), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(Source),
            Blocks(Paragraph(Text(description))), role);

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "The genuine accumulation set of normalized quadratic approximations equals the signed nonzero norm spectrum of the actual trace dual.",
        H("Quadratic accumulation classification"), Blocks(
            Paragraph(Text("Dhanda and Haynes, Theorem 4, classify the complete accumulation set of normalized approximations to a real quadratic irrational. The classification below uses the actual real field generated by the irrational and its actual trace-dual lattice. The norm-value inclusion is supplied by signed_norm_values_accumulate in QuadraticAccumulation; the converse follows from an elementary discreteness argument.")),
            Paragraph(Text("The radicand is an arbitrary squarefree integer at least two. The constant and square-root coefficients are rational, and the latter is nonzero, including negative coefficients. Denominators range over all nonzero integers and numerators over all integers; there is no coprimality, maximal-order, integral-coefficient or additional unit hypothesis.")),
            Item("derivedSet_eq_signed_norm_values", "For every squarefree integer radicand at least two and arbitrary rational coefficients with nonzero square-root coefficient, the derived set of all normalized approximation values is exactly the set of both signed scaled field norms of nonzero elements of the actual trace dual. Negative square-root coefficients and negative integer denominators are included.", DescribeRole.Theorem),
            Paragraph(Text("For the converse, values in a bounded interval with bounded integer denominator have bounded integer numerator, hence form a finite set. A punctured accumulation neighborhood can avoid that finite set. For every natural bound and positive tolerance this gives an approximation with a larger absolute denominator. Selecting tolerances tending to zero gives normalized errors converging to the proposed accumulation point while the absolute denominators tend to infinity; the unnormalized errors therefore tend to zero.")),
            Paragraph(Text("For integer coordinates q and p the exact dual vector has coordinates q/2 and (p-Aq)/(2DB). Its trace pairings are q and p. Write delta for twice B times the positive square root of D and e for q alpha minus p. The exact identity delta N(s) = q e - e squared/delta relates its norm to the normalized error. A common denominator for the three rational coefficients of this binary quadratic norm form puts all its values on one fixed rational grid.")),
            Paragraph(Text("Multiply the norm label by the sign of q before taking limits. The signed scaled norm differs from the normalized error by a signed multiple of e squared/delta, which tends to zero. Multiplication by the fixed rational grid denominator and division by delta give integer labels converging to the correspondingly scaled limit. Closedness and discreteness of the integer embedding force eventual equality of these labels with their limit. Any index in this tail supplies a nonzero dual vector, since its first coordinate is q/2 and q is nonzero. Transporting this vector, its trace pairings and its norm through the existing coordinate equivalence gives the required vector in the actual generated real field. The denominator sign determines which of the two signed norm values is obtained; symmetry is used only in the previously proved opposite inclusion.")))));
}
